begin;
create schema notes_test;
create table notes_test.results(name text primary key,passed boolean not null);
create table notes_test.state(k text primary key,v jsonb);
grant usage on schema notes_test to anon,authenticated,service_role;
grant select,insert,update on all tables in schema notes_test to anon,authenticated,service_role;
create function notes_test.assert(name text,ok boolean) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'ASSERTION FAILED: %',name; end if;
insert into notes_test.results values(name,true); end $$;
create function notes_test.denied(name text,command text,expected text) returns void language plpgsql as $$
declare caught boolean:=false; begin begin execute command; exception when others then
if sqlerrm not like '%'||expected||'%' then raise; end if; caught:=true; end;
perform notes_test.assert(name,caught); end $$;
insert into auth.users(id,email_confirmed_at) values
('70000000-0000-4000-8000-000000000001',now()),('70000000-0000-4000-8000-000000000002',now()),('70000000-0000-4000-8000-000000000009',null);
insert into public.movies(id,tmdb_id,title,original_title) values
('70000000-0000-4000-8000-000000000003',77777,'Notes fixture','Notes fixture');
set local role anon;
insert into notes_test.state values('empty-summary',public.get_movie_summary('70000000-0000-4000-8000-000000000003'));
select notes_test.assert('empty timeline neutral',public.get_movie_notes('70000000-0000-4000-8000-000000000003')='{"notes":[],"nextOffset":null}');
select notes_test.denied('anon raw notes denied','select * from private.movie_notes','permission denied');
select notes_test.denied('anon reports denied','select * from private.note_reports','permission denied');
select notes_test.denied('anon operator audit denied','select * from private.note_operator_actions','permission denied');
select notes_test.denied('anon own notes denied',$cmd$select public.get_my_movie_notes('70000000-0000-4000-8000-000000000003')$cmd$,'permission denied');
select notes_test.denied('anonymous helper denied',$cmd$select * from private.note_category_levels('70000000-0000-4000-8000-000000000003')$cmd$,'permission denied');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
insert into notes_test.state values('note',public.put_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',0,true,'animal_harm','<img src=x onerror=alert(1)>; DROP TABLE public.movies;',null,null,null,2::smallint,'notes-first'));
select notes_test.assert('markup stored as literal plaintext',(select v->'note'->>'comment' from notes_test.state where k='note')='<img src=x onerror=alert(1)>; DROP TABLE public.movies;');
select notes_test.assert('untimed note accepted',(select v->'note'->'startSeconds'='null'::jsonb from notes_test.state where k='note'));
select notes_test.assert('idempotent replay unchanged',public.put_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',0,true,'animal_harm','<img src=x onerror=alert(1)>; DROP TABLE public.movies;',null,null,null,2::smallint,'notes-first')=(select v from notes_test.state where k='note'));
select notes_test.denied('changed body conflicts',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',0,true,'animal_harm','Different',null,null,null,2::smallint,'notes-first')$cmd$,'IDEMPOTENCY_CONFLICT');
select notes_test.denied('stale revision conflicts',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',0,true,'animal_harm','Different',null,null,null,2::smallint,'notes-stale')$cmd$,'REVISION_CONFLICT');
select notes_test.denied('empty untimed rejects',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,true,'animal_harm',null,null,null,null,0::smallint,'notes-empty')$cmd$,'INVALID_REQUEST');
select notes_test.denied('overlong prose rejects',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,true,'animal_harm',repeat('x',281),null,null,null,0::smallint,'notes-length')$cmd$,'INVALID_REQUEST');
select notes_test.denied('end without start rejects',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,true,'animal_harm','Text',null,1,null,0::smallint,'notes-end')$cmd$,'INVALID_REQUEST');
select notes_test.denied('backward interval rejects',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,true,'animal_harm',null,100,99,null,0::smallint,'notes-backward')$cmd$,'INVALID_REQUEST');
select notes_test.denied('out of range timestamp rejects',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,true,'animal_harm',null,86401,null,null,0::smallint,'notes-range')$cmd$,'INVALID_REQUEST');
select notes_test.denied('invalid spoiler rejects',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,true,'animal_harm','Text',null,null,null,3::smallint,'notes-level')$cmd$,'INVALID_REQUEST');
select notes_test.denied('watch confirmation required',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,false,'animal_harm','Text',null,null,null,0::smallint,'notes-watch')$cmd$,'WATCH_CONFIRMATION_REQUIRED');
select notes_test.denied('overlong version rejects',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,true,'animal_harm','Text',null,null,repeat('x',81),0::smallint,'notes-version')$cmd$,'INVALID_REQUEST');
select notes_test.assert('own sees hidden prose',jsonb_array_length(public.get_my_movie_notes('70000000-0000-4000-8000-000000000003')->'notes')=1);
select notes_test.denied('authenticated raw notes denied','select * from private.movie_notes','permission denied');
set local role anon;
select notes_test.assert('category spoiler invisible entirely',public.get_movie_notes('70000000-0000-4000-8000-000000000003')='{"notes":[],"nextOffset":null}');
select notes_test.assert('level1 cannot expose level2',public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['animal_harm'],1::smallint,20,0)='{"notes":[],"nextOffset":null}');
select notes_test.assert('unrelated reveal cannot expose hidden category',public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['nudity'],2::smallint,20,0)='{"notes":[],"nextOffset":null}');
select notes_test.assert('selected full reveal exposes note',jsonb_array_length(public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['animal_harm'],2::smallint,20,0)->'notes')=1);
select notes_test.assert('public note has no author identifier',not((public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['animal_harm'],2::smallint,20,0)->'notes'->0) ? 'userId'));
select notes_test.denied('invalid reveal empty categories rejects',$cmd$select public.get_movie_notes('70000000-0000-4000-8000-000000000003','{}',2::smallint,20,0)$cmd$,'INVALID_REQUEST');
select notes_test.denied('overlarge pagination rejects',$cmd$select public.get_movie_notes('70000000-0000-4000-8000-000000000003','{}',0::smallint,51,0)$cmd$,'INVALID_REQUEST');
select notes_test.denied('duplicate category rejects',$cmd$select public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['animal_harm','animal_harm'],0::smallint,20,0)$cmd$,'INVALID_REQUEST');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select notes_test.assert('other user own empty',public.get_my_movie_notes('70000000-0000-4000-8000-000000000003')='{"notes":[]}');
select notes_test.denied('cross owner write denied',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',(select (v->'note'->>'revision')::bigint from notes_test.state where k='note'),true,'animal_harm','Take over',null,null,null,0::smallint,'notes-steal')$cmd$,'FORBIDDEN');
select notes_test.denied('cross owner delete denied',$cmd$select public.delete_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',(select (v->'note'->>'revision')::bigint from notes_test.state where k='note'),'notes-delete-other')$cmd$,'FORBIDDEN');
select notes_test.assert('report submitted',public.report_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',(select (v->'note'->>'revision')::bigint from notes_test.state where k='note'),'spoiler','Private correction','notes-report')='{"reported":true}');
select notes_test.assert('report duplicate not weighted',public.report_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',(select (v->'note'->>'revision')::bigint from notes_test.state where k='note'),'spoiler','Private correction','notes-report-again')='{"reported":true}');
select notes_test.denied('stale report rejects',$cmd$select public.report_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',999,'spoiler',null,'notes-report-stale')$cmd$,'REVISION_CONFLICT');
select notes_test.denied('invalid reason rejects',$cmd$select public.report_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',1,'other',null,'notes-report-bad')$cmd$,'INVALID_REQUEST');
select public.patch_warning('70000000-0000-4000-8000-000000000003',0,true,'animal_harm',3::smallint,0::smallint,array['animal_death'],'notes-rating');
select public.put_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000005',0,true,'animal_harm',null,0,5,'Theatrical',0::smallint,'notes-time',3::smallint);
select notes_test.denied('scene severity out of range rejects',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,true,'animal_harm','Text',null,null,null,0::smallint,'notes-severity',6::smallint)$cmd$,'INVALID_REQUEST');
set local role anon;
select notes_test.assert('note hides rating aggregates fully',public.get_movie_summary('70000000-0000-4000-8000-000000000003')=(select v from notes_test.state where k='empty-summary'));
select notes_test.assert('strongest note hides other authors notes',public.get_movie_notes('70000000-0000-4000-8000-000000000003')='{"notes":[],"nextOffset":null}');
select notes_test.assert('selected note page reports visible next offset',public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['animal_harm'],2::smallint,1,0)->>'nextOffset'='1');
select notes_test.assert('timestamp zero valid and no prose required',(public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['animal_harm'],2::smallint,20,0)->'notes'->0) @> '{"comment":null,"startSeconds":0,"endSeconds":5,"version":"Theatrical","severity":3}');
select notes_test.assert('unknown severity remains null',(public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['animal_harm'],2::smallint,20,0)->'notes'->1)->'severity'='null'::jsonb);
reset role;
select notes_test.assert('report correction private stored',(select count(*)=1 and bool_and(correction='Private correction') from private.note_reports));
insert into private.movie_notes(id,user_id,movie_id,category_slug,start_seconds,spoiler_level,revision,created_at) values
('70000000-0000-4000-8000-000000000006','70000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000003','language',90,0,100,now()-interval '2 days'),
('70000000-0000-4000-8000-000000000007','70000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000003','language',10,0,101,now()-interval '1 day');
set local role anon;
select notes_test.assert('timeline orders by scene time not insertion',(public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['language'],0::smallint,1,0)->'notes'->0)->>'id'='70000000-0000-4000-8000-000000000007');
reset role;
update private.movie_notes set spoiler_level=1 where id='70000000-0000-4000-8000-000000000006';
set local role anon;
select notes_test.assert('hidden timestamps cannot influence default order',(public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['language'],0::smallint,1,0)->'notes'->0)->>'id'='70000000-0000-4000-8000-000000000006');
select notes_test.assert('explicit reveal restores chronological order',(public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['language'],1::smallint,1,0)->'notes'->0)->>'id'='70000000-0000-4000-8000-000000000007');
reset role;
delete from private.movie_notes where id in('70000000-0000-4000-8000-000000000006','70000000-0000-4000-8000-000000000007');
-- Change level2 note to detail level; category details conservatively hidden too.
update private.movie_notes set spoiler_level=1 where id='70000000-0000-4000-8000-000000000004';
set local role anon;
select notes_test.assert('detail level masks every note prose timestamp version',not exists(select 1 from jsonb_array_elements(public.get_movie_notes('70000000-0000-4000-8000-000000000003')->'notes') n where n->'comment'<>'null'::jsonb or n->'version'<>'null'::jsonb or n->'startSeconds'<>'null'::jsonb));
select notes_test.assert('detail level keeps factual scene severity',exists(select 1 from jsonb_array_elements(public.get_movie_notes('70000000-0000-4000-8000-000000000003')->'notes') n where n->>'severity'='3'));
select notes_test.assert('detail note hides rating descriptors',exists(select 1 from jsonb_array_elements(public.get_movie_summary('70000000-0000-4000-8000-000000000003')->'warnings') w where w @> '{"category":"animal_harm","severity":3,"descriptors":[]}'));
select notes_test.assert('selected detail reveal exposes version',(public.get_movie_notes('70000000-0000-4000-8000-000000000003',array['animal_harm'],1::smallint,20,0)->'notes'->0)->>'version'='Theatrical');
reset role;
update public.category_ratings set spoiler_level=2 where category_slug='animal_harm' and contribution_id in(select id from public.contributions where movie_id='70000000-0000-4000-8000-000000000003');
set local role anon;
select notes_test.assert('rating hides notes in reverse direction',public.get_movie_notes('70000000-0000-4000-8000-000000000003')='{"notes":[],"nextOffset":null}');
reset role;
update public.category_ratings set spoiler_level=0 where category_slug='animal_harm' and contribution_id in(select id from public.contributions where movie_id='70000000-0000-4000-8000-000000000003');
update private.user_access set status='suspended' where user_id='70000000-0000-4000-8000-000000000001';
set local role anon;
select notes_test.assert('suspended author no longer affects disclosure',(public.get_movie_notes('70000000-0000-4000-8000-000000000003')->'notes'->0)->>'version'='Theatrical');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
select notes_test.denied('suspended writer denied',$cmd$select public.get_my_movie_notes('70000000-0000-4000-8000-000000000003')$cmd$,'ACCOUNT_SUSPENDED');
reset role;
update private.user_access set status='active' where user_id='70000000-0000-4000-8000-000000000001';
update private.movie_notes set visibility='hidden' where id='70000000-0000-4000-8000-000000000004';
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select notes_test.denied('moderator hidden note cannot be reported or probed',$cmd$select public.report_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',(select (v->'note'->>'revision')::bigint from notes_test.state where k='note'),'abuse',null,'notes-hidden-report')$cmd$,'NOT_FOUND');
reset role;
update private.movie_notes set visibility='active' where id='70000000-0000-4000-8000-000000000004';
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
select notes_test.denied('self report denied',$cmd$select public.report_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',(select (v->'note'->>'revision')::bigint from notes_test.state where k='note'),'abuse',null,'notes-self')$cmd$,'FORBIDDEN');
select notes_test.assert('own delete works',public.delete_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',(select (v->'note'->>'revision')::bigint from notes_test.state where k='note'),'notes-delete')='{"deleted":true}');
select notes_test.assert('delete replay works',public.delete_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',(select (v->'note'->>'revision')::bigint from notes_test.state where k='note'),'notes-delete')='{"deleted":true}');
select notes_test.denied('tombstone UUID cannot resurrect',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000004',0,true,'animal_harm','Revive',null,null,null,0::smallint,'notes-revive')$cmd$,'FORBIDDEN');
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000009',true);
select notes_test.denied('unverified account denied',$cmd$select public.get_my_movie_notes('70000000-0000-4000-8000-000000000003')$cmd$,'EMAIL_NOT_VERIFIED');
reset role;
update private.request_buckets set count=10 where subject_hash='70000000-0000-4000-8000-000000000002' and action='contribution' and window_seconds=60;
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select notes_test.denied('quota shared with warning writes',$cmd$select public.put_movie_note('70000000-0000-4000-8000-000000000003',gen_random_uuid(),0,true,'animal_harm','Text',null,null,null,0::smallint,'notes-quota')$cmd$,'RATE_LIMITED');
reset role;
update public.movies set visibility='hidden' where id='70000000-0000-4000-8000-000000000003';
set local role anon;
select notes_test.denied('hidden movie notes not found',$cmd$select public.get_movie_notes('70000000-0000-4000-8000-000000000003')$cmd$,'NOT_FOUND');
reset role;
select notes_test.assert('narrow roles no schema create',not has_schema_privilege('triggerboxd_writer','private','CREATE') and not has_schema_privilege('triggerboxd_reader','public','CREATE'));
select notes_test.assert('writer cannot moderate via delete',not has_table_privilege('triggerboxd_writer','private.note_operator_actions','INSERT'));
select notes_test.assert('reader cannot mutate notes',not has_table_privilege('triggerboxd_reader','private.movie_notes','UPDATE'));
select notes_test.assert('service raw notes denied',not has_table_privilege('service_role','private.movie_notes','SELECT'));
insert into private.note_operator_actions(operator_reference,note_id,report_id,action,reason,target_revision)
select 'test owner',note_id,id,'resolve','Test resolution',target_revision from private.note_reports;
delete from auth.users where id='70000000-0000-4000-8000-000000000001';
select notes_test.assert('account deletion cleans authors notes and corrections',not exists(select 1 from private.movie_notes where user_id='70000000-0000-4000-8000-000000000001') and not exists(select 1 from private.note_reports));
select notes_test.assert('account deletion retains nonpersonal audit',(select count(*)=1 and bool_and(note_id is null and report_id is null) from private.note_operator_actions));
select name,passed from notes_test.results order by name;
rollback;
